<?php
require 'config.php';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_POST['remove']))unset($_SESSION['cart'][(int)$_POST['remove']]);elseif(isset($_POST['update'])){foreach($_POST['qty']??[] as $id=>$qty){$id=(int)$id;$qty=max(0,(int)$qty);if($qty===0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=$qty;}}go('cart.php');}
$items=[];$total=0;if(!empty($_SESSION['cart'])){$ids=array_keys($_SESSION['cart']);$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE active=1 AND id IN ($in)");$s->execute($ids);foreach($s as $p){$qty=min((int)$_SESSION['cart'][$p['id']],(int)$p['stock']);if($qty<1){unset($_SESSION['cart'][$p['id']]);continue;}$sub=$qty*$p['price'];$total+=$sub;$items[]=['p'=>$p,'qty'=>$qty,'sub'=>$sub];}}
$page_title='Keranjang';require 'header.php';?><h1>Keranjang belanja</h1><?php if(!$items):?><p class="empty">Keranjang masih kosong. <a href="index.php">Cari produk</a></p><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="table-wrap"><table><tr><th>Produk</th><th>Harga</th><th>Jumlah</th><th>Subtotal</th><th></th></tr><?php foreach($items as $it):$p=$it['p'];?><tr><td><?=e($p['name'])?></td><td><?=rupiah($p['price'])?></td><td><input class="qty" type="number" name="qty[<?=$p['id']?>]" min="0" max="<?=$p['stock']?>" value="<?=$it['qty']?>"></td><td><?=rupiah($it['sub'])?></td><td><button class="link-btn" name="remove" value="<?=$p['id']?>">Hapus</button></td></tr><?php endforeach;?></table></div><button class="btn secondary" name="update" value="1">Perbarui keranjang</button></form><div class="checkout-bar"><h2>Total: <?=rupiah($total)?></h2><a class="btn" href="checkout.php">Lanjut checkout</a></div><?php endif;?><?php require 'footer.php';?>